UPDATE user_profile
SET liked_foods = #{likedFoods,typeHandler=com.syde.mealplanner.config.typehandler.ListStringJsonTypeHandler},
    disliked_foods = #{dislikedFoods,typeHandler=com.syde.mealplanner.config.typehandler.ListStringJsonTypeHandler},
    allergies = #{allergies,typeHandler=com.syde.mealplanner.config.typehandler.ListStringJsonTypeHandler}
WHERE user_id = #{userId}
